import { ArrowLeft, ArrowRight, Check, ChevronRight, CircleAlert, Code2, Copy, ExternalLink, FileCode2, FolderOpen, Globe2, History, LayoutTemplate, LoaderCircle, LockKeyhole, MessageSquare, Monitor, PanelLeft, Plus, RefreshCw, Rocket, Save, Search, Send, Settings2, ShieldCheck, Smartphone, Sparkles, Square, Upload, X } from 'lucide-react';
